    ('public.clinic_edit_invoice_core(uuid,text,jsonb,jsonb)', 'fcd2e7ffbe990448ce9ffd5ca1a3a2a2'),
    ('public.clinic_refund_source_core(uuid)', '6879a31e67a2fcbc97b12bcd410aee1d')
    ) f(sig, md5)
  union all select 'security definer: ' || f.sig, f.v, (select prosecdef::text from pg_proc where oid = to_regprocedure(f.sig))
    from (values
    ('public.clinic_save_initial_record(uuid,uuid,jsonb,jsonb,jsonb,jsonb,uuid,uuid,text,text,text)', 'false'),
    ('public.clinic_save_inpatient_log(uuid,uuid,jsonb,jsonb,jsonb,text)', 'false'),
    ('public.clinic_post_invoice(uuid,text,jsonb,jsonb)', 'true'),
    ('public.clinic_void_reissue_invoice_core(uuid,text,text)', 'true'),
    ('public.clinic_edit_invoice_core(uuid,text,jsonb,jsonb)', 'true'),
    ('public.clinic_refund_source_core(uuid)', 'true')
